import LottieView from "lottie-react-native";
import React from "react";
import { View } from "react-native";
import { useReducedMotion } from "react-native-reanimated";
import { useTheme } from "../theme";

// Generated by scripts/generate-lottie.py. Layer names are the colorFilters
// keypaths, so both animations follow the theme (and CMS colour overrides).
const SUCCESS_CHECK = require("../../assets/animations/success-check.json");
const CELEBRATE_BURST = require("../../assets/animations/celebrate-burst.json");

/** A check that draws itself in a disc. Under reduced motion, just the finished check. */
export function SuccessCheck({ size = 24 }: { size?: number }) {
  const { colors } = useTheme();
  const reduceMotion = useReducedMotion();
  return (
    <View accessibilityElementsHidden importantForAccessibility="no-hide-descendants" style={{ width: size, height: size }}>
      <LottieView
        source={SUCCESS_CHECK}
        autoPlay={!reduceMotion}
        progress={reduceMotion ? 1 : undefined}
        loop={false}
        style={{ width: size, height: size }}
        colorFilters={[
          { keypath: "Disc", color: colors.primary },
          { keypath: "Ring", color: colors.primary },
          { keypath: "Check", color: colors.buttonText },
        ]}
      />
    </View>
  );
}

/**
 * A one-shot ring + confetti burst, centred on whatever it's placed over
 * (lay it absolutely behind an icon). Draws nothing under reduced motion.
 */
export function CelebrationBurst({ size = 120 }: { size?: number }) {
  const { colors } = useTheme();
  const reduceMotion = useReducedMotion();
  if (reduceMotion) return null;
  return (
    <View
      pointerEvents="none"
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={{ width: size, height: size }}
    >
      <LottieView
        source={CELEBRATE_BURST}
        autoPlay
        loop={false}
        style={{ width: size, height: size }}
        colorFilters={[
          { keypath: "Pulse", color: colors.primary },
          { keypath: "DotsA", color: colors.primary },
          { keypath: "DotsB", color: colors.secondary },
        ]}
      />
    </View>
  );
}
